class Tarih:
    def __init__(self, gun, ay):
        self.gun, self.ay = gun, ay

    @classmethod
    def metinden(cls, metin):
        g, a = metin.split(".")
        return cls(int(g), int(a))

    @staticmethod
    def gecerli_ay(a):
        return 1 <= a <= 12

t = Tarih.metinden("29.10")
print(t.ay, Tarih.gecerli_ay(13))
